export const umrahHistory=[
 {title:'Дом, возведённый для поклонения',text:'Ибрахим и Исма‘ил, мир им, возводили Каабу и просили Аллаха принять их труд. В Умре паломник направляется к этому Дому ради поклонения Аллаху.',refs:['hajar']},
 {title:'История Хаджар',text:'Когда в долине закончилась вода, Хаджар искала помощь между Сафой и Марвой. Её семь переходов и появление Замзама напоминают о старании и уповании на Аллаха. Этот рассказ связан с происхождением са‘й.',refs:['hajar']},
 {title:'Путь после Худайбии',text:'Пророка ﷺ и его сподвижников не допустили в Мекку для Умры. По соглашению они смогли вернуться в следующем году. Эта Умра стала частью истории терпения и выполнения договора.',refs:['treaty']}
];
export const umrahSteps=[
 {id:'prepare',title:'Подготовка к дороге',chapter:'Перед ихрамом',image:'prepare',caption:'Одежда, чистота и необходимые вещи.',paragraphs:['Изучите маршрут и заранее узнайте, где будете проходить микат. Подготовьте одежду ихрама и необходимые вещи; до вступления в ихрам рекомендуется полное омовение.','Мужчина надевает изар и рида — два полотнища. Женщина остаётся в дозволенной закрытой одежде; специальный белый комплект для неё не требуется.'],refs:['jabir','clothing','women']},
 {id:'miqat',title:'Не пропустите микат',chapter:'Граница пути',image:'miqat',caption:'Схема пути: микат определяется вашим маршрутом.',paragraphs:['Микат — установленная граница вступления в ихрам для тех, кто направляется на Умру. Выберите её по своему пути. Из Медины проходят через Зуль-Хулейфу.','Если летите сразу в Мекку, подготовьтесь заранее и вступите в ихрам до пересечения миката. Одного переодевания недостаточно: важно намерение совершить Умру.'],note:'Если вы уже в Мекке или пропустили микат, уточните свой случай у знающего сопровождающего.',refs:['miqat','guide']},
 {id:'ihram',title:'Намерение и тальбия',chapter:'Начало Умры',image:'talbiya',caption:'Ихрам начинается с намерения, затем произносится тальбия.',paragraphs:['На микате примите намерение совершить Умру и вступите в ихрам. Произносите тальбию по дороге к Мекке. Это обращение к Аллаху, а не отсчёт повторений.'],formula:{arabic:'لَبَّيْكَ اللَّهُمَّ لَبَّيْكَ، لَبَّيْكَ لَا شَرِيكَ لَكَ لَبَّيْكَ، إِنَّ الْحَمْدَ وَالنِّعْمَةَ لَكَ وَالْمُلْكَ، لَا شَرِيكَ لَكَ',transcription:'Ляббайка Аллаахумма ляббайк. Ляббайка ля шариика ляка ляббайк. Инналь-хамда уан-ни‘мата ляка уаль-мульк. Ля шариика ляк.',meaning:'О Аллах, я отвечаю на Твой призыв. У Тебя нет сотоварища. Тебе принадлежат хвала, милость и власть.'},refs:['talbiya']},
 {id:'limits',title:'Сохраняйте состояние ихрама',chapter:'В пути',image:'limits',caption:'Не стригите волосы и не наносите ароматические средства.',paragraphs:['До завершения обрядов соблюдайте ограничения ихрама: не удаляйте волосы и ногти, не пользуйтесь парфюмом, воздерживайтесь от супружеской близости.','Мужчины не надевают рубашку, брюки и головной убор. Женщины не надевают никаб и перчатки; вопросы покрытия лица при посторонних и исключений при необходимости имеют отдельные правила.'],note:'При болезни или нарушении ихрама уточните порядок действий у знающего человека.',refs:['clothing','women','tawaf','guide']},
 {id:'arrival',title:'Прибытие в Заповедную мечеть',chapter:'Мекка',image:'arrival',caption:'Кааба — направление обхода; поклонение обращено к Аллаху.',paragraphs:['Следуйте указателям и спокойно войдите в мечеть. Перед тавафом совершите омовение. Подойдите к линии Чёрного камня, от которой начинается обход.','Если у женщины началась менструация, она может вступить в ихрам, но таваф откладывает до очищения. Согласуйте дальнейший порядок с сопровождающим.'],refs:['jabir','purity','guide']},
 {id:'tawaf',title:'Таваф: семь полных кругов',chapter:'Вокруг Каабы',image:'tawaf',caption:'Против часовой стрелки. Кааба остаётся слева.',paragraphs:['Начните у линии Чёрного камня и двигайтесь вокруг Каабы, оставляя её слева. Возвращение к исходной линии завершает один круг. Всего — семь кругов. Обход проходит снаружи Хиджра, полукруглой ограды рядом с Каабой.','Если нельзя приблизиться к камню без тесноты, укажите в его сторону и произнесите такбир. Не толкайте людей. Читайте Коран, зикр и дуа; отдельная обязательная молитва для каждого круга не установлена.'],detail:{title:'Для мужчин: рамаль и идыба‘',text:'В тавафе Умры мужчина открывает правое плечо; в первых трёх кругах идёт бодрым шагом, если это не причиняет вреда людям. После тавафа плечо закрывают. Женщины идут обычным шагом.'},refs:['jabir','stone','shoulder','guide']},
 {id:'prayer',title:'Два ракаата после тавафа',chapter:'Перед са‘й',image:'prayer',caption:'Место молитвы выбирайте так, чтобы не мешать обходу.',paragraphs:['После семи кругов совершите два ракаата. Если возможно, молитесь за макамом Ибрахима; при тесноте выберите другое свободное место в мечети.','Затем направляйтесь к Сафе по указателям. Можно попить Замзам, не задерживая движение других паломников.'],refs:['tawaf','jabir','guide']},
 {id:'safa',title:'Начните с Сафы',chapter:'Начало са‘й',image:'safa',caption:'Первый переход начинается на Сафе.',paragraphs:['На Сафе обратитесь в сторону Каабы, поминайте Аллаха и делайте дуа. В описании Джабира ﷺ переданы такбир, слова единобожия и мольба между ними. На Марве поступайте так же.','Начните движение к Марве. Путь Сафа → Марва считается первым переходом, а обратный путь — вторым.'],refs:['jabir','tawaf']},
 {id:'sai',title:'Са‘й: семь переходов',chapter:'Сафа и Марва',image:'sai',caption:'Сафа → Марва = 1. Марва → Сафа = 2. Седьмой заканчивается на Марве.',paragraphs:['Пройдите семь переходов между Сафой и Марвой. Начало — Сафа, завершение — Марва. Не считайте путь туда и обратно одним переходом.','Мужчины, которым это по силам и безопасно, ускоряются между зелёными отметками. Женщины проходят весь путь обычным шагом. Поминайте Аллаха и просите Его о том, что вам нужно.'],refs:['jabir','guide']},
 {id:'finish',title:'Укорачивание волос и завершение',chapter:'Выход из ихрама',image:'finish',caption:'Завершение — после тавафа и са‘й.',paragraphs:['После са‘й мужчина сбривает волосы или укорачивает их по всей голове. Сбривание предпочтительнее. Женщина укорачивает концы волос; голову она не сбривает.','После этого Умра завершена и ограничения ихрама снимаются. Простое переодевание или уход в гостиницу не заменяет завершения обрядов.'],note:'Объём укорачивания волос уточните по правилам вашей правовой школы.',refs:['hair','womenHair','guide']}
];
export const pilgrimTips=[
 {id:'route',title:'До вылета',text:'Уточните микат по маршруту, действующие документы и разрешения через официальные сервисы. Сохраните адрес гостиницы и контакты сопровождающего.',refs:['miqat','nusuk']},
 {id:'crowd',title:'В большой группе',text:'Договоритесь о месте встречи, следуйте указателям и указаниям сотрудников. Не останавливайтесь посреди потока ради фотографии.',refs:['guide']},
 {id:'water',title:'Вода и отдых',text:'Возьмите воду, отдыхайте в тени и не торопитесь. При недомогании обратитесь к сотрудникам за медицинской помощью.',refs:['guide']},
 {id:'accessible',title:'Если трудно ходить',text:'Заранее уточните доступные коляски и маршруты на месте. Выбирайте помощь по своим силам, не пытайтесь идти через опасную тесноту.',refs:['guide']},
 {id:'women',title:'Женщинам',text:'Белый цвет одежды не обязателен. При менструации таваф откладывается до очищения; не выходите из ихрама самостоятельно из-за изменения плана.',refs:['women','purity']},
 {id:'madinah',title:'Поездка в Медину',text:'Посещение мечети Пророка ﷺ — отдельная часть поездки, не этап Умры. Порядок посещения Рауды и доступные записи уточняйте в Nusuk.',refs:['guide','nusuk']}
];
export function validUmrahProgress(value){return !!value&&value.edition===UMRAH_EDITION&&Number.isInteger(value.index)&&value.index>=0&&value.index<umrahSteps.length&&typeof value.complete==='boolean'}
export function umrahRoute(hash){const query=new URLSearchParams(String(hash).split('?')[1]||'');const step=umrahSteps.findIndex(row=>row.id===query.get('step'));return {view:['history','tips','imams','complete'].includes(query.get('view'))?query.get('view'):step>=0?'lesson':'home',step:Math.max(0,step),mosque:query.get('mosque')==='madinah'?'madinah':'mecca',month:query.get('month'),day:query.get('day')}}
